window.VO = [{"id":"s01","text":"Dig straight down from India, and you'd think you'd hit America.","at":0.5,"t0":0.25,"t1":3.43},{"id":"s02","text":"You won't. Delhi comes out in the Pacific. So do Mumbai, Bengaluru, Chennai and Kolkata.","at":7.46,"t0":3.73,"t1":9.305},{"id":"s03","text":"Almost all of India does. The big exception: a patch of desert outside Jaisalmer.","at":19.51,"t0":9.755,"t1":15.09},{"id":"s04","text":"Its other side is Easter Island, and its giant stone heads.","at":30.88,"t0":15.44,"t1":18.765},{"id":"s05","text":"Now dig. The deepest hole ever drilled is twelve kilometres. Barely a scratch.","at":38.53,"t0":19.265,"t1":24.065},{"id":"s06","text":"Below, it gets hotter, until the core: as hot as the surface of the Sun.","at":48.93,"t0":24.465,"t1":28.615},{"id":"s07","text":"Now jump. You'd shoot through the centre faster than a satellite.","at":58.13,"t0":29.065,"t1":32.33},{"id":"s08","text":"Thirty-eight minutes later, you'd pop out next to the stone heads.","at":65.26,"t0":32.63,"t1":35.82},{"id":"s09","text":"The root cause of all those splashes? Only fifteen percent of land has land on its other side.","at":72.74,"t0":36.37,"t1":42.005},{"id":"s10","text":"And with no air in the tunnel, you'd fall back. And forth. Forever.","at":85.01,"t0":42.505,"t1":46.37}];
